def count_loss_regions(pnl, limit):
    rows = len(pnl)
    cols = len(pnl[0]) if rows else 0
    seen = set()
    count = 0
    for r in range(rows):
        for c in range(cols):
            if pnl[r][c] < -limit and (r, c) not in seen:
                count += 1
                seen.add((r, c))
                stack = [(r, c)]
                while stack:
                    a, b = stack.pop()
                    for x, y in ((a - 1, b), (a + 1, b), (a, b - 1), (a, b + 1)):
                        if 0 <= x < rows and 0 <= y < cols and pnl[x][y] < -limit and (x, y) not in seen:
                            seen.add((x, y))
                            stack.append((x, y))
    return count
